UPDATE proofs SET body_tex = '\emph{(1)} \textbf{$A_k$ is an average of $g$ against a positive kernel.} Put $g(u) = \mathcal G_\psi(e^u)$, a real function. Substituting $x = e^u$ gives $\mathcal H_\psi(s) = \int_0^\infty g(u)\, e^{-su}\,du$, and \hyperref[8JT3]{differentiating $k$ times under the integral} gives
\[ A_k(\sigma + i\tau) = \int_0^\infty g(u)\, K_k(u)\, e^{-i\tau u}\,du, \qquad K_k(u) = \frac{u^k e^{-\sigma u}}{k!} \ge 0. \]

\emph{(2)} \textbf{Because the kernel is positive, only an upper bound for $g$ is needed.} As $|e^{-i\tau u}| = 1$ and $|g| + g = 2g_+$ with $g_+ = \max(g, 0)$,
\[ |A_k(\sigma + i\tau)| + \Re A_k(\sigma) \le \int_0^\infty (|g| + g)\, K_k = 2\int_0^\infty g_+ K_k. \]

\emph{(3)} \textbf{The kernel is a sharp peak at $u = k/\sigma$, and multiplying it by $e^{au}$ just replaces $\sigma$ by $\sigma - a$.} For $a < \sigma$,
\[ e^{au} K_k(u) = (\sigma - a)^{-k-1}\, p_{\sigma - a}(u), \qquad p_\beta(u) = \frac{\beta^{k+1} u^k e^{-\beta u}}{k!}, \]
where $p_\beta$ is the density of the Gamma distribution with shape $k+1$ and rate $\beta$, with mean $(k+1)/\beta$. In particular $\int_0^\infty e^{au} K_k = (\sigma - a)^{-k-1}$, and by Chernoff''s bound, for $0 < \eta < 1$,
\[ \int_{|u - (k+1)/\beta| > \eta (k+1)/\beta} p_\beta(u)\,du \le 2 e^{-c(\eta)\, k}, \qquad c(\eta) = \eta - \log(1+\eta) > 0. \]
Panel (a) shows $K_1, K_2, K_3$ for $\sigma = 1$. Panel (b) shows the kernel rescaled to height $1$ at its peak,
\[ \frac{K_k(u)}{K_k(k/\sigma)} = \Bigl(\frac{\sigma u}{k}\Bigr)^{k} e^{k - \sigma u}, \]
for $k = 3, 30, 300$, with $U$ chosen so that $k/\sigma = \frac54 U$; the shaded band is the window $W$ of (4). As $k$ grows, almost all of the kernel lies inside $W$.
\includegraphics[width=1, alt=The kernel K_k for k = 1, 2, 3, and rescaled kernels for k = 3, 30, 300 aimed at the window from U to 3U/2]{/static/figures/gamma-kernel.svg}

\emph{(4)} \textbf{Choose $k$ so that the peak sits in the middle of the window where the hypothesis holds.} With $x = e^u$ and $U = \log Y$, the window $Y \le x \le Y^{3/2}$ becomes $W = [U, \frac32 U]$, whose midpoint is $\frac54 U$. So take
\[ k = \bigl\lceil \tfrac54 \sigma U \bigr\rceil, \qquad \text{so that } k/\sigma \approx \tfrac54 U. \]
On $W$ the hypothesis gives $g_+(u) \le e^{\theta u}$, so
\begin{align*}
\int_W g_+ K_k &\le \int_W e^{\theta u} K_k(u)\,du && (g_+ \le e^{\theta u} \text{ on } W) \\
&\le \int_0^\infty e^{\theta u} K_k(u)\,du && (K_k \ge 0) \\
&= (\sigma - \theta)^{-k-1} && \text{(by (3) with } a = \theta).
\end{align*}

\emph{(5)} \textbf{Outside the window the crude growth of $g$ only moves the peak slightly, which is harmless once $\sigma$ is large.} Off $W$ we only know $g_+ \le C_\psi e^{2u}$ from \ref{8JS3}, so we use (3) with $a = 2$: the peak moves to $m = (k+1)/(\sigma - 2)$ and the mass becomes $(\sigma - 2)^{-k-1}$. Fix $\eta > 0$ with $\frac54 (1+\eta)^2 < \frac32$, and $\sigma_0 > 2$ with
\[ \frac{\sigma_0}{\sigma_0 - 2} < \min\bigl(1 + \eta,\ e^{c(\eta)}\bigr); \]
this then holds for every $\sigma \ge \sigma_0$ in place of $\sigma_0$. Then $\frac54 U \le m \le \frac54 (1+\eta) U + o(U)$, so $[(1-\eta)m, (1+\eta)m] \subset W$ for large $U$, and
\begin{align*}
\int_{u \notin W} g_+ K_k &\le C_\psi \int_{u \notin W} e^{2u} K_k(u)\,du && (g_+ \le C_\psi e^{2u}) \\
&= C_\psi\, (\sigma - 2)^{-k-1} \int_{u \notin W} p_{\sigma - 2}(u)\,du && \text{(by (3) with } a = 2) \\
&\le 2 C_\psi\, (\sigma - 2)^{-k-1} e^{-c(\eta) k} && (\text{Chernoff, as } [(1-\eta)m, (1+\eta)m] \subset W) \\
&\le 2 C_\psi\, (\sigma - \theta)^{-k} && \Bigl(\tfrac{\sigma - \theta}{\sigma - 2} < \tfrac{\sigma}{\sigma - 2} < e^{c(\eta)}\Bigr).
\end{align*}

\emph{(6)} \textbf{Every $Y$ from the hypothesis gives one good $k$, so there are infinitely many.} Let $K$ be the set of $k = \lceil \frac54 \sigma \log Y \rceil$ for the $Y$ given by the hypothesis that are large enough for (5); it is infinite because these $Y$ are unbounded. For $k \in K$ and $\tau \in \R$, splitting the integral of (2) at the window,
\begin{align*}
|A_k(\sigma + i\tau)| + \Re A_k(\sigma) &\le 2\int_W g_+ K_k + 2\int_{u \notin W} g_+ K_k && \text{(by (2))} \\
&\le 2(\sigma - \theta)^{-k-1} + 4 C_\psi\, (\sigma - \theta)^{-k} && \text{(by (4) and (5))} \\
&\le (2 + 4 C_\psi)\, (\sigma - \theta)^{-k} && (\sigma - \theta \ge 1),
\end{align*}
which is the claim with $C = 2 + 4 C_\psi$.', body_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-24 19:40:00', updated_by = 'claude' WHERE id = 109;
